// One Bright Data input per keyword. The dataset takes {url, keyword} and
// rejects the URL on its own - posting {url} alone answers
// "keyword: Required field" with an HTTP 200.
//
// single-item input: Settings emits one row of configuration.
const cfg = $('Settings').first().json;

const domain = String(cfg.amazon_domain || 'https://www.amazon.com')
  .trim()
  .replace(/\/+$/, '');

const keywords = String(cfg.keywords || '')
  .split(',')
  .map(k => k.trim())
  .filter(Boolean);

if (!keywords.length) {
  throw new Error(
    'Settings.keywords is empty. Put a comma separated list of search terms ' +
    'there, for example: wireless earbuds, standing desk'
  );
}

// Measured 2026-09-02: adding &page=1 to the URL does not limit the crawl.
// The same request still returned seven pages. Only limit_per_input on the
// trigger URL does, so the URL stays a plain search.
const payload = keywords.slice(0, 25).map(k => ({
  url: domain + '/s?k=' + encodeURIComponent(k).replace(/%20/g, '+'),
  keyword: k,
}));

return [{
  json: {
    payload,
    keyword_count: payload.length,
    dropped: Math.max(0, keywords.length - payload.length),
  },
}];

// Bright Data answers validation errors and rate limits with HTTP 200 and an
// error body, so the status code says nothing. The payload is the only honest
// check, and retryOnFail would swallow it.
//
// single-item input: one snapshot is being polled.
const p = $input.first().json || {};

if (p.error) {
  throw new Error(
    'Bright Data refused the crawl: ' + JSON.stringify(p.error).slice(0, 300)
  );
}

const status = String(p.status || '');

if (status === 'failed') {
  throw new Error(
    'The crawl failed at Bright Data. Snapshot ' + (p.snapshot_id || 'unknown') +
    '. Check the dataset in the Bright Data dashboard before rerunning.'
  );
}

// $runIndex is how many times this node has already run in this execution, so
// it is the poll count. Without a cap a snapshot that never finishes keeps the
// execution alive until the instance is restarted.
const polls = $runIndex + 1;
const MAX_POLLS = 20;

if (status !== 'ready' && polls >= MAX_POLLS) {
  throw new Error(
    'The crawl was still running after ' + polls + ' checks, about ' +
    (polls * 15) + ' seconds. A capped Amazon search normally finishes in ' +
    'about 11 seconds per keyword, so either results_per_keyword is very high ' +
    'or Bright Data is backed up. Snapshot ' + (p.snapshot_id || 'unknown')
  );
}

return [{
  json: {
    snapshot_id: p.snapshot_id,
    status,
    ready: status === 'ready',
    records: p.records || 0,
    polls,
  },
}];

// The one that matters.
//
// `sponsored` arrives as the STRING "false", not the boolean. Measured on
// 941 rows: 941 of 941 were strings, while is_prime, is_coupon and
// is_banner_product in the same rows are real booleans. A non-empty string is
// truthy, so `if (row.sponsored)` is true for every organic result and the
// naive filter keeps nothing. That failure is silent: every node stays green
// and the report says you rank nowhere.
const isAd = r => String(r.sponsored).toLowerCase() === 'true';

// Amazon titles are 200 characters of keyword stuffing. Cutting at a fixed
// length lands mid-word and the report reads like it broke.
function trim(s, n) {
  const t = String(s || '').trim();
  if (t.length <= n) return t;
  const cut = t.slice(0, n);
  const space = cut.lastIndexOf(' ');
  return (space > n - 25 ? cut.slice(0, space) : cut).replace(/[,\s|-]+$/, '') + '...';
}

const rows = $input.all()
  .map(i => i.json)
  .filter(r => r && r.asin && r.keyword);

if (!rows.length) {
  throw new Error(
    'The snapshot came back empty. That usually means the keyword returned no ' +
    'results on this Amazon domain, or the crawl was capped to zero.'
  );
}

const byKeyword = {};
for (const r of rows) {
  const k = String(r.keyword);
  if (!byKeyword[k]) byKeyword[k] = { organic: [], ads: [] };
  (isAd(r) ? byKeyword[k].ads : byKeyword[k].organic).push(r);
}

const out = [];

for (const keyword of Object.keys(byKeyword)) {
  const bucket = byKeyword[keyword];

  // Ranks restart at 1 on every page and the page size is not a constant -
  // 16 organic results per page for one keyword and 48 for another, in the
  // same snapshot. So the absolute position is counted, not calculated from
  // a page size. Sorting by (page, rank) and numbering the survivors is the
  // only arithmetic that holds for both.
  const ordered = bucket.organic
    .slice()
    .sort((a, b) =>
      (a.page_number || 1) - (b.page_number || 1) ||
      (a.rank_on_page || 0) - (b.rank_on_page || 0)
    );

  // The same ASIN comes back on more than one page of a deep crawl, and as an
  // ad as well as an organic result - six of 25 rows on one keyword. Keeping
  // the first sighting means a product holds one position, not five.
  const seen = new Set();
  let position = 0;
  const results = [];

  for (const r of ordered) {
    if (seen.has(r.asin)) continue;
    seen.add(r.asin);
    position += 1;
    results.push({
      position,
      // The slot Amazon put it in, kept alongside the counted position because
      // the two disagree and the difference is information. Measured on five
      // capped crawls of one keyword: the returned ranks ran 1-21 and then
      // jumped to 31, so nine slots on that page were never in the payload.
      page_slot: r.rank_on_page || 0,
      asin: r.asin,
      title: trim(r.name, 150),
      brand: r.brand || null,
      price: Number(r.final_price) || 0,
      rating: Number(r.rating) || 0,
      reviews: Number(r.num_ratings) || 0,
      badge: r.badge || null,
      page: r.page_number || 1,
      url: r.url || '',
    });
  }

  const adAsins = Array.from(new Set(bucket.ads.map(a => a.asin)));

  out.push({
    json: {
      keyword,
      results,
      organic_count: results.length,
      ad_count: adAsins.length,
      ad_asins: adAsins,
      ad_titles: bucket.ads.slice(0, 10).map(a => String(a.name || '').slice(0, 120)),
    },
  });
}

return out;

// Your position, your share of the slots, and who is above you.
const cfg = $('Settings').first().json;

const brand = String(cfg.your_brand || '').trim().toLowerCase();
const depth = Math.max(3, Number(cfg.shelf_depth) || 10);

const myAsins = new Set(
  String(cfg.your_asins || '')
    .split(',')
    .map(s => s.trim().toUpperCase())
    .filter(Boolean)
);

if (!brand && !myAsins.size) {
  throw new Error(
    'Settings needs your_brand or your_asins - without one of them there is ' +
    'nothing to find a position for.'
  );
}

// `brand` is null on 87% of rows (822 of 941 measured), so a brand filter that
// only reads that field misses almost everything. The title carries the brand
// on Amazon far more reliably than the brand field does.
function isMine(r) {
  if (myAsins.has(String(r.asin).toUpperCase())) return true;
  if (!brand) return false;
  if (String(r.brand || '').toLowerCase().includes(brand)) return true;
  return String(r.title || '').toLowerCase().includes(brand);
}

const out = [];

for (const item of $input.all()) {
  const d = item.json;
  const results = d.results || [];
  const shelf = results.slice(0, depth);

  const mine = results.filter(isMine);
  const best = mine.length ? mine[0] : null;
  const slotsHeld = shelf.filter(isMine).length;

  // A paid slot is not a rank, but knowing you hold one matters. Ads are
  // reported as a count of what actually arrived and never as a share of the
  // page: five capped crawls of the same keyword minutes apart returned
  // sponsored rows once and none the other four times, so a percentage here
  // would swing between 44% and 0% while the page had not changed.
  const adAsins = new Set((d.ad_asins || []).map(a => String(a).toUpperCase()));
  const payingHere = Array.from(myAsins).some(a => adAsins.has(a));

  const above = shelf
    .filter(r => !isMine(r) && (!best || r.position < best.position))
    .slice(0, 5)
    .map(r => ({
      position: r.position,
      asin: r.asin,
      title: r.title,
      price: r.price,
      rating: r.rating,
      reviews: r.reviews,
    }));

  out.push({
    json: {
      keyword: d.keyword,
      best_position: best ? best.position : 0,
      // The slot Amazon gave it. It matches the counted position only when
      // every slot above it came back in the payload.
      best_slot: best ? best.page_slot : 0,
      best_asin: best ? best.asin : '',
      best_title: best ? best.title : '',
      best_price: best ? best.price : 0,
      slots_held: slotsHeld,
      shelf_depth: depth,
      organic_seen: d.organic_count || 0,
      ads_seen: d.ad_count || 0,
      running_ads: payingHere,
      top_asin: results.length ? results[0].asin : '',
      top_title: results.length ? results[0].title : '',
      above,
    },
  });
}

return out;

// reads the table: $input is the stored history, on purpose. The fresh numbers
// come from Measure Your Shelf by name, because a Data Table read replaces the
// item the same way a Set node does.
const fresh = $('Measure Your Shelf').all().map(i => i.json);

const history = {};
for (const item of $input.all()) {
  const r = item.json || {};
  if (r.keyword) history[String(r.keyword)] = r;
}

const moves = [];

for (const f of fresh) {
  const prev = history[f.keyword];
  const before = prev ? Number(prev.best_position) || 0 : null;
  const now = Number(f.best_position) || 0;

  // 0 means "not in the results we looked at", which is a real state and not a
  // position. Treating it as position zero would make every absent keyword the
  // best rank on the board.
  let change = 'first look';
  let delta = 0;

  if (before !== null) {
    if (before === 0 && now === 0) change = 'still absent';
    else if (before === 0 && now > 0) change = 'entered';
    else if (before > 0 && now === 0) change = 'dropped out';
    else if (before === now) change = 'unchanged';
    else {
      delta = before - now;
      change = delta > 0 ? 'up' : 'down';
    }
  }

  moves.push(Object.assign({}, f, {
    previous_position: before === null ? '' : before,
    change,
    delta,
    notable:
      change === 'entered' ||
      change === 'dropped out' ||
      change === 'first look' ||
      Math.abs(delta) >= (Number($('Settings').first().json.alert_on_move) || 3),
  }));
}

const notable = moves.filter(m => m.notable);

return [{
  json: {
    moves,
    notable,
    notable_count: notable.length,
    keyword_count: moves.length,
  },
}];

// single-item input: one comparison covering every keyword.
const d = $input.first().json;
const cfg = $('Settings').first().json;
const lines = [];

lines.push('*Amazon shelf* - ' + d.notable_count + ' of ' + d.keyword_count +
  ' keywords moved');
lines.push('');

const arrow = { up: ':arrow_up:', down: ':arrow_down:', entered: ':new:',
  'dropped out': ':x:', 'first look': ':eyes:' };

// A full Amazon title is 150 characters of keyword stuffing and unreadable in
// a Slack line. The first clause is the product.
function short(t) {
  const s = String(t || '').split(/\s[|,-]\s|\s\|/)[0].trim();
  return s.length > 72 ? s.slice(0, 69).replace(/[\s,|-]+$/, '') + '...' : s;
}

for (const m of d.notable) {
  const where = m.best_position
    ? 'organic #' + m.best_position
    : 'not in the top ' + m.organic_seen;

  let head = (arrow[m.change] || ':white_small_square:') + ' *' + m.keyword +
    '* - ' + where;

  if (m.change === 'up' || m.change === 'down') {
    head += ' (was #' + m.previous_position + ', ' +
      (m.delta > 0 ? '+' : '') + m.delta + ')';
  }
  lines.push(head);

  const held = m.slots_held
    ? m.slots_held + ' of the top ' + m.shelf_depth + ' slots'
    : 'no slots in the top ' + m.shelf_depth;

  const notes = [held, 'read ' + m.organic_seen + ' organic results'];

  // Only said when sponsored rows were genuinely in the payload. Their absence
  // is not evidence that the page carried no ads - the same keyword returned
  // them once in five capped crawls.
  if (m.ads_seen) {
    notes.push(m.ads_seen + ' paid placements' +
      (m.running_ads ? ', one of them yours' : ''));
  }
  lines.push('    ' + notes.join(' | '));

  // Amazon's own slot number, said only when it disagrees with the counted
  // position - which means slots above it were not in the payload.
  if (m.best_position && m.best_slot && m.best_slot !== m.best_position) {
    lines.push('    Amazon put it in slot ' + m.best_slot +
      ', so ' + (m.best_slot - m.best_position) +
      ' slots above it were not in the results we received');
  }

  const above = (m.above || []).slice(0, 3);

  // The listings above you already start at the top slot, so naming it
  // separately printed the same 150 character title twice.
  if (!above.length && m.best_position !== 1 && m.top_title) {
    lines.push('    top slot: ' + short(m.top_title));
  }

  for (const a of above) {
    lines.push('    #' + a.position + ' ' + short(a.title) +
      (a.price ? ' - $' + a.price : '') +
      (a.rating ? ' - ' + a.rating + '* (' + a.reviews + ')' : ''));
  }
  lines.push('');
}

lines.push('_Positions count the organic results only, in the order Amazon returned ' +
  'them. Sponsored placements never enter the numbering._');

return [{ json: { message: lines.join('\n').slice(0, 3800) } }];

// One row per keyword, whether or not it moved - the history is the point.
const moves = $('Compare With Yesterday').first().json.moves || [];
const today = new Date().toISOString().slice(0, 10);

return moves.map(m => ({
  json: {
    keyword: String(m.keyword),
    best_position: Number(m.best_position) || 0,
    slots_held: Number(m.slots_held) || 0,
    organic_seen: Number(m.organic_seen) || 0,
    top_asin: String(m.top_asin || ''),
    checked_on: today,
  },
}));
